# -*- coding: utf-8 -*-

import subprocess
from ..utils import DEVNULL, change_working_directory
from .base import DOWNLOAD_CONTAINER


def _checkout(name):
    with change_working_directory(DOWNLOAD_CONTAINER):
        subprocess.call(
            ('git', 'checkout', name),
            stdout=DEVNULL, stderr=subprocess.STDOUT,
        )


def download(source_info):
    url = source_info['git']
    c_kwargs = dict(
        stdout=DEVNULL, stderr=subprocess.STDOUT,
    )
    subprocess.call(('git', 'clone', '--recurse-submodules', url, DOWNLOAD_CONTAINER), **c_kwargs)
    if 'tag' in source_info:
        _checkout(source_info['tag'])
    elif 'branch' in source_info:
        _checkout(source_info['branch'])

# imports
from flask import render_template, Blueprint

from project import db   # pragma: no cover
from project.models import Person   # pragma: no cover

import random


# config
home_blueprint = Blueprint(
    'home', __name__,
    template_folder='templates'
)   # pragma: no cover
MAX_GRID_SIZE_HOMEPAGE = 6


# routes
# use decorators to link the function to a url
@home_blueprint.route('/', methods=['GET', 'POST'])   # pragma: no cover
def home():
    error = None
    current_person_count = db.session.query(Person).count()
    if current_person_count <= MAX_GRID_SIZE_HOMEPAGE:
        persons = db.session.query(Person).all()
    else:
        random_person_ids = []
        while len(random_person_ids) < MAX_GRID_SIZE_HOMEPAGE:
            rand = random.randint(0, current_person_count-1)
            if rand not in random_person_ids:
                random_person_ids.append(rand)
        persons = []
        for val in random_person_ids:
            persons.append(db.session.query(Person)[val])
    return render_template(
        'index.html', persons=persons, error=error)

