@register.filter()
def bootstrap(field,cols=None):
    if not field.__class__.__name__ == "MultiWidget":
        if field.field.widget.input_type == "checkbox":
            return "%s<div class='checkbox'%s>%s</div>" % (
                        field,
                        " style='margin-left:%s;'" % "padding-left" if cols else "",
                        field.errors.as_html(),
                    )
        elif field.field.widget.input_type == "radio":
            return "<div%s class='radio'%s>%s%s</div>" % (
                        "style='margin-left:%s;'" % "padding-left" if cols else "",
                        field,
                        field.errors.as_html(),
                        field.as_widget(),
                    )
        return "<div%s'%s>%%s%s</div>'%%(
                    'style='margin-left:%s;' % 'padding-left' if cols else '',
                    field,
                    field.errors.as_html(),
                    field.as_widget(),
                    "padding-left" if cols else "",
                )
    final = '<div%s>%%s%s</div>'%(
                'style='margin-left:%s;' % 'padding-left' if cols else '',
