from django import template
from django.template.defaulttags import url
from django.template.library import parsed_link_if_string_argument
from django.core.urlresolvers import NoReverseMatch
from django.template import Node, Variable, VariableDoesNotExist

register = template.Library()

@register.tag
def page_title(parser, token):
    """
    .. template_function:: page_title request

    Add the content to the `head.title` block.

    Usage::

        {% page_title %}My Title{% endpage_title %}

    """
    nodelist = parser.parse(('endpage_title',))
    parser.delete_first_token()
    return TitleNode(nodelist)

class TitleNode(Node):
    def __init__(self, nodelist):
        self.nodelist = nodelist

    def render(self, context):
        return self.nodelist.render(context)

@register.tag
def add_body_class(parser, token):
    """
    Adds the given class to the `body` tag `class` attribute.

    Usage::

        {% add_body_class "some-class" %}

    """
    parsed = parsed_link_if_string_argument(parser, token)
    if parsed.link is None:
        raise template.TemplateSyntaxError("%r tag requires an string argument" % token.contents.split()[0])
    return AddClassNode(parsed.link)

class AddClassNode(Node):
    def __init__(self, value):
        self.value = value

    def render(self, context):
        existing = context.get('body_class', '')
        var = Variable(self.value)
        value = var.resolve(context)
        context['body_class'] = u'%s %s' % (existing, value)
        return ''

@register.tag
def add_css(parser, token):
    """
    Load the given CSS file in the `head.css` block.

    Usage::

        {% add_css "custom.css" %}

    """
    parsed = parsed_link_if_string_argument(parser, token)
    if parsed.link is None:
        raise template.TemplateSyntaxError("%r tag requires an string argument" % token.contents.split()[0])
    return AddCssNode(parsed.link)

class AddCssNode(Node):
    def __init__(self, value):
        self.value = value

    def render(self, context):
        existing = context.get('head.css', "")
        value = "/%s" % self.value
        if not value in existing:
            context['head.css'] = u'%s%s' % (existing, value)
        return ''

@register.tag
def add_js(parser, token):
    """
    Load the given JS file in the `head.js` block.

    Usage::

        {% add_js "custom.js" %}

    """
    parsed = parsed_link_if_string_argument(parser, token)
    if parsed.link is None:
        raise template.TemplateSyntaxError("%r tag requires an string argument" % token.contents.split()[0])
    return AddJsNode(parsed.link)

class AddJsNode(Node):
    def __init__(self, value):
        self.value = value

    def render(self, context):
        existing = context.get('head.js', "")
        value = "/%s" % self.value
        if not value in existing:
            context['head.js'] = u'%s%s' % (existing, value)
