@register.tag()
def bind(parser, token):
    """
    Binds an object to a variable, without affecting the current context.

    This is roughly equivalent to:

    .. code-block:: html+django

        {% with foo as %}

    For example:

    .. code-block:: html+django

        {% bind "latitude, longitude, units = coordinates()" %}
        <p>The latitude is {{ latitude }}</p>
        <p>The longitude is {{ longitude }}</p>
        <p>The units are {{ units }}</p>

    You can bind virtually anything---function calls, variable lookups,
    list/tuple unpacking, and even simple math should all work fine.

    When would you use this? Consider the following example:

    .. code-block:: html+django

        <div class="{{ field.css_classes }}">
            {{ field.label_tag }}
            {{ field }}
            {% if field.help_text %}
                <p class="help-inline">{{ field.help_text|safe }}</p>
            {% endif %}
            {{ field.errors }}
        </div>

    What if you want to override the CSS class on the ``field.errors`` div? You
    might be tempted to do something like this:

    .. code-block:: html+django

        <div class="{{ field.css_classes }}">
            {{ field.label_tag }}
            {{ field }}
            {% if field.help_text %}
                <p class="help-inline">{{ field.help_text|safe }}</p>
            {% endif %}
            <div class="error">
                {{ field.errors }}
            </div>
        </div>

    But wait! Now your CSS classes have changed---the ``field.errors`` div no
    longer has the correct class. With ``bind``, you can do this:

    .. code-block:: html+django

        {% bind CSS_ERROR = "error" %}
        <div class="{{ field.css_classes }}">
            {{ field.label_tag }}
            {{ field }}
            {% if field.help_text %}
                <p class="help-inline">{{ field.help_text|safe }}</p>
            {% endif %}
            <div class="{{ CSS_ERROR }}">
                {{ field.errors }}
            </div>
        </div>

    This keeps the ``field.css_classes`` up to date and leaves the ``error``
    class isolated. Neato!

    Note that you do not need to bind simple strings to a variable. The above
    example could have easily been written like this:

    .. code-block:: html+django

        <div class="{{ field.css_classes }}">
            {{ field.label_tag }}
            {{ field }}
            {% if field.help_text %}
                <p class="help-inline">{{ field.help_text|safe }}</p>
            {% endif %}
            <div class="error">
                {{ field.errors }}
            </div>
        </div>

    But when doing more complicated binding, this technique comes in handy.

    """
    split = token.split_contents()
    split = split[1:]
    payload = ', '.join(split)
    return BindNode.payload)

class BindNode(template.Node):
    def __init__(self, payload):
        self.payload = payload

    def render(self, context):
        vals = self.payload.split('=')
        expr = vals[-1]
        names = vals[0].replace(' ', '').split(',')
        values = context[expr]
        for i in range(len(names)):
            if len(names) == 1:
                # Only one name, doesn't need unpacking
                binding = values
            else:
                # Needs unpacking
                binding = values[i]
            context.push()
            context[names[i]] = binding
        return ''

